// The only place to configure this workflow. The applicant profile deliberately does
// NOT live here: it is a row in the database, so the same workflow serves any applicant.
const SUPABASE_URL = '';   // TODO: https://<project>.supabase.co
const CHAT_ID = '';        // TODO: chat that receives the alerts
const PROFILE_ID = 'default';
const ALERT_THRESHOLD = 70;

if (!SUPABASE_URL) throw new Error('SUPABASE_URL is not configured in "Config"');
if (!CHAT_ID) throw new Error('CHAT_ID is not configured in "Config"');

const base = SUPABASE_URL.replace(/\/+$/, '');
return [{
  json: {
    chatId: CHAT_ID,
    alertThreshold: ALERT_THRESHOLD,
    profileUrl: base + '/rest/v1/applicant_profile?id=eq.' + PROFILE_ID + '&limit=1',
    // Only JSON sources are implemented, see the README. The filter keeps an
    // unimplemented row from silently producing empty results.
    sourcesUrl: base + '/rest/v1/funding_sources?enabled=eq.true&kind=eq.json',
    storeUrl: base + '/rest/v1/funding_items',
  },
}];

// Maps every source into one shape. Sources are rows, not code: each carries a dot path
// to its item array and a map from our field names to theirs, so adding a source is an
// insert rather than an edit here.
//
// "Fetch source" runs once per source row, so the fetched responses line up with
// $('Load sources') by position. That positional pairing is why a failed fetch must
// still emit an item, which is what onError: continueRegularOutput guarantees.
// An empty or missing path must mean "not mapped", not "the whole object": reduce over
// an empty key list would otherwise return obj itself and every unmapped field would
// become "[object Object]" instead of falling back to the default.
const get = (obj, path) => {
  const keys = String(path || '').split('.').filter(Boolean);
  if (!keys.length) return undefined;
  return keys.reduce((acc, key) => (acc === null || acc === undefined ? undefined : acc[key]), obj);
};

const label = (x) => (x && typeof x === 'object' && 'label' in x ? x.label : x);
const text = (x) => (x === null || x === undefined ? '' : String(label(x)));

const parseMoney = (x) => {
  const n = parseFloat(text(x).replace(/[^0-9.]/g, ''));
  return Number.isFinite(n) ? n : null;
};
const parseDate = (x) => {
  const t = Date.parse(text(x));
  return Number.isFinite(t) ? new Date(t).toISOString().slice(0, 10) : null;
};

const sources = $('Load sources').all().map((i) => i.json);
const fetched = $input.all();

const items = [];
for (let idx = 0; idx < fetched.length; idx++) {
  const json = fetched[idx].json || {};
  const source = sources[idx];
  if (!source) continue;

  const rawList = get(json, source.items_path) || json.results || json.items || [];
  const list = Array.isArray(rawList) ? rawList : [rawList];
  const map = source.field_map || {};

  for (const raw of list) {
    if (!raw || typeof raw !== 'object') continue;
    const nativeId = text(get(raw, map.id) ?? raw.id ?? raw.guid ?? get(raw, map.url) ?? raw.link);
    const title = text(get(raw, map.title) ?? raw.title).trim();
    if (!nativeId || !title) continue;

    // The text is kept because quote verification later needs the exact string the
    // model was shown, not a re-fetch that may have changed.
    const summary = text(get(raw, map.summary) ?? raw.summary ?? raw.description ?? '')
      .replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim();

    items.push({
      id: source.name + ':' + nativeId,
      source: source.name,
      title,
      url: text(get(raw, map.url) ?? raw.url ?? raw.link) || null,
      deadline: parseDate(get(raw, map.deadline) ?? raw.deadline),
      budget: parseMoney(get(raw, map.budget) ?? raw.budget),
      country: (text(get(raw, map.country) ?? raw.country) || '').toUpperCase() || null,
      summary: summary.slice(0, 4000),
    });
  }
}

const cfg = $('Config').first().json;
return [{
  json: {
    source: 'eu-funding',
    key_field: 'id',
    items,
    fetched: items.length,
    chatId: cfg.chatId,
    alertThreshold: cfg.alertThreshold,
    storeUrl: cfg.storeUrl,
  },
}];

// The cheap gate. Everything decidable in code is decided here, before a single token
// is spent: deadlines, budget, country, required and disqualifying terms. The counters
// it emits are what make "most candidates never reach the model" checkable rather than
// a claim.
const dedup = $input.first().json || {};
const state = $('Normalise items').first().json;
const profile = $('Load applicant profile').first().json || {};

const arr = (x) => (Array.isArray(x) ? x : []);
const keywords = arr(profile.keywords).map((k) => String(k).toLowerCase());
const exclude = arr(profile.exclude_terms).map((k) => String(k).toLowerCase());
const countries = arr(profile.countries).map((c) => String(c).toUpperCase());
const budgetMin = profile.budget_min === null || profile.budget_min === undefined ? null : Number(profile.budget_min);
const budgetMax = profile.budget_max === null || profile.budget_max === undefined ? null : Number(profile.budget_max);

const today = new Date().toISOString().slice(0, 10);
const candidates = Array.isArray(dedup.new_items) ? dedup.new_items : [];

const dropped = { deadline: 0, budget: 0, country: 0, keywords: 0, excluded: 0 };
const kept = [];

for (const item of candidates) {
  const haystack = (item.title + ' ' + item.summary).toLowerCase();

  if (item.deadline && item.deadline < today) { dropped.deadline++; continue; }
  if (budgetMin !== null && item.budget !== null && item.budget < budgetMin) { dropped.budget++; continue; }
  if (budgetMax !== null && item.budget !== null && item.budget > budgetMax) { dropped.budget++; continue; }
  if (countries.length && item.country && !countries.includes(item.country)) { dropped.country++; continue; }
  if (exclude.length && exclude.some((t) => haystack.includes(t))) { dropped.excluded++; continue; }
  if (keywords.length && !keywords.some((k) => haystack.includes(k))) { dropped.keywords++; continue; }

  kept.push(item);
}

return [{
  json: {
    items: kept,
    considered: candidates.length,
    kept: kept.length,
    dropped,
    droppedTotal: candidates.length - kept.length,
    profile: {
      domains: arr(profile.domains),
      keywords: arr(profile.keywords),
      countries,
      budget_min: budgetMin,
      budget_max: budgetMax,
      notes: profile.notes || '',
    },
    chatId: state.chatId,
    alertThreshold: state.alertThreshold,
    storeUrl: state.storeUrl,
  },
}];

// One scoring call for everything that survived the cheap gate.
const gate = $input.first().json;
const items = gate.items;

const list = items.map((it) => [
  'id: ' + it.id,
  'title: ' + it.title,
  it.deadline ? 'deadline: ' + it.deadline : null,
  it.budget !== null ? 'budget: ' + it.budget : null,
  it.country ? 'country: ' + it.country : null,
  'url: ' + (it.url || 'none'),
  'text: ' + it.summary,
].filter(Boolean).join('\n')).join('\n\n---\n\n');

const p = gate.profile;
const profileText = [
  'domains: ' + p.domains.join(', '),
  'keywords: ' + p.keywords.join(', '),
  'countries: ' + (p.countries.length ? p.countries.join(', ') : 'any'),
  'budget range: ' + (p.budget_min ?? 'any') + ' to ' + (p.budget_max ?? 'any'),
  p.notes ? 'notes: ' + p.notes : null,
].filter(Boolean).join('\n');

return [{
  json: {
    ...gate,
    system: 'You score European funding calls against one applicant profile. You never'
      + ' invent evidence: evidence_quote must be copied verbatim from the text you were'
      + ' given, and it is checked afterwards.',
    user: 'Applicant profile:\n' + profileText
      + '\n\nScore each call below. evidence_quote must be an exact substring of that'
      + " call's own text. If you cannot find supporting text, return an empty"
      + ' evidence_quote and a low score.\n\n' + list,
    max_retries: 2,
    schema: {
      type: 'object',
      required: ['items'],
      properties: {
        items: {
          type: 'array',
          items: {
            type: 'object',
            required: ['id', 'relevance_0_100', 'evidence_quote'],
            properties: {
              id: { type: 'string' },
              relevance_0_100: { type: 'integer' },
              matched_criteria: { type: 'array', items: { type: 'string' } },
              blocking_reasons: { type: 'array', items: { type: 'string' } },
              evidence_quote: { type: 'string' },
              evidence_url: { type: 'string' },
            },
          },
        },
      },
    },
  },
}];

// Quote verification. This is the part that makes the scores worth anything: a quote
// the model produced must be a literal substring of the text that model was given.
// Anything else is marked unverified and capped, never silently trusted.
const UNVERIFIED_CAP = 40;

const llm = $input.first().json || {};
const gate = $('Build scoring request').first().json;

const scored = llm.ok && llm.data && Array.isArray(llm.data.items) ? llm.data.items : [];
const byId = new Map(scored.map((s) => [s.id, s]));

// Whitespace differs harmlessly between the prompt and the source text; nothing else is
// normalised, so a paraphrase still fails.
const norm = (s) => String(s || '').replace(/\s+/g, ' ').trim().toLowerCase();

let unverifiedCount = 0;
const rows = gate.items.map((item) => {
  const s = byId.get(item.id) || {};
  const quote = String(s.evidence_quote || '').trim();
  const haystack = norm(item.title + ' ' + item.summary);
  const verified = quote.length >= 12 && haystack.includes(norm(quote));
  if (!verified) unverifiedCount++;

  const raw = Number.isInteger(s.relevance_0_100) ? s.relevance_0_100 : 0;
  const relevance = verified ? Math.max(0, Math.min(100, raw)) : Math.min(raw, UNVERIFIED_CAP);

  return {
    id: item.id,
    source: item.source,
    title: item.title,
    url: item.url,
    deadline: item.deadline,
    budget: item.budget,
    country: item.country,
    summary: item.summary.slice(0, 1000),
    relevance,
    matched: Array.isArray(s.matched_criteria) ? s.matched_criteria : [],
    blocking: Array.isArray(s.blocking_reasons) ? s.blocking_reasons : [],
    evidence: verified ? quote : null,
    evidence_url: s.evidence_url || item.url || null,
    unverified: !verified,
    alerted: false,
  };
});

const alerts = rows.filter((r) => r.relevance >= gate.alertThreshold && !r.unverified);
for (const a of alerts) a.alerted = true;
rows.sort((a, b) => b.relevance - a.relevance);

const esc = (s) => String(s)
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

const parts = alerts.length ? ['<b>Funding radar: ' + alerts.length + ' worth a look</b>', ''] : [];
for (const a of alerts.slice().sort((x, y) => y.relevance - x.relevance)) {
  parts.push('<b>' + a.relevance + '</b> · ' + esc(a.source)
    + (a.deadline ? ' · deadline ' + esc(a.deadline) : ''));
  parts.push(a.url ? '<a href="' + a.url + '">' + esc(a.title) + '</a>' : esc(a.title));
  if (a.matched.length) parts.push('matches: ' + esc(a.matched.slice(0, 3).join(', ')));
  if (a.evidence) parts.push('<i>' + esc(a.evidence.slice(0, 200)) + '</i>');
  parts.push('');
}
if (alerts.length) {
  parts.push('<i>' + gate.considered + ' seen, ' + gate.droppedTotal + ' filtered before scoring'
    + (unverifiedCount ? ', ' + unverifiedCount + ' unverified' : '') + '</i>');
}

return [{
  json: {
    rows,
    stored: rows.length,
    alertCount: alerts.length,
    unverifiedCount,
    considered: gate.considered,
    droppedTotal: gate.droppedTotal,
    dropped: gate.dropped,
    degraded: !llm.ok,
    chatId: gate.chatId,
    storeUrl: gate.storeUrl,
    text: parts.join('\n').trim(),
  },
}];
